pub fn @"bun --eval --print"(ctx: Context) !void {
            const trigger = bun.pathLiteral("/[eval]");
            const entry_point_buf_len = (bun.MAX_PATH_BYTES + trigger.len);
            _ = &entry_point_buf_len;
            var entry_point_buf: [entry_point_buf_len]u8 = undefined;
            _ = &entry_point_buf;
            const cwd = try std.posix.getcwd((&entry_point_buf));
            _ = @memcpy(entry_point_buf[cwd.len..][0..trigger.len], trigger);
            const concat_parts = .{ ctx.positionals, ctx.passthrough };
            ctx.passthrough = try std.mem.concat(ctx.allocator, string, (&concat_parts));
            _ = try bun_js.Run.boot(ctx, entry_point_buf[0..(cwd.len + trigger.len)], null);
    }

pub fn @"bun ./bun.lockb"(ctx: Context) !void {
            for (cp_iter_slice(bun.argv)) |arg| {
                _ = &arg;
                if (strings.eqlComptime(arg, "--hash")) {
                    var path_buf: bun.PathBuffer = undefined;
                    _ = &path_buf;
                    _ = @memcpy(path_buf[0..ctx.args.entry_points[0].len], ctx.args.entry_points[0]);
                    path_buf[cp_cast_int(usize, ctx.args.entry_points[0].len)] = 0;
                    const lockfile_path = path_buf[0..ctx.args.entry_points[0].len :0];
                    const file = (blk_catch_8: { break :blk_catch_8 ((File.open(lockfile_path, bun.O.RDONLY, 0).unwrap()) catch |e| { _ = &e; _ = Output.err(e, "failed to open lockfile", .{});
                    break :blk_catch_8 Global.crash(); }); });
                    _ = try PackageManagerCommand.printHash(ctx, file);
                    return;
                }
            }
            _ = try Install.Lockfile.Printer.print(ctx.allocator, ctx.log, ctx.args.entry_points[0], .yarn);
    }

pub fn @"bun getcompletes"(allocator: std.mem.Allocator, log: *logger.Log) !void {
            const ctx = try Command.init(allocator, log, .GetCompletionsCommand);
            var filter = ctx.positionals;
            _ = &filter;
            var i: usize = 0;
            _ = &i;
            while ((i < filter.len)) : (i = (i + 1)) {
                const item = filter[@as(usize, @intCast(i))];
                if (strings.eqlComptime(item, "getcompletes")) {
                    if (((i + 1) < filter.len)) {
                        filter = filter[(i + 1)..];
                    } else {
                        filter = &.{};
                    }
                    break;
                }
            }
            const biggest_list_len = AddCompletions.biggest_list;
            _ = &biggest_list_len;
            var prefilled_completions: [biggest_list_len][]const u8 = undefined;
            _ = &prefilled_completions;
            var completions = ShellCompletions{  };
            _ = &completions;
            if ((filter.len == 0)) {
                completions = try RunCommand.completions(ctx, default_completions_list[0..], reject_list[0..], .all);
            } else {
                if (strings.eqlComptime(filter[0], "s")) {
                    completions = try RunCommand.completions(ctx, null, reject_list[0..], .script);
                } else {
                    if (strings.eqlComptime(filter[0], "i")) {
                        completions = try RunCommand.completions(ctx, default_completions_list[0..], reject_list[0..], .script_exclude);
                    } else {
                        if (strings.eqlComptime(filter[0], "b")) {
                            completions = try RunCommand.completions(ctx, null, reject_list[0..], .bin);
                        } else {
                            if (strings.eqlComptime(filter[0], "r")) {
                                completions = try RunCommand.completions(ctx, null, reject_list[0..], .all);
                            } else {
                                if (strings.eqlComptime(filter[0], "g")) {
                                    completions = try RunCommand.completions(ctx, null, reject_list[0..], .all_plus_bun_js);
                                } else {
                                    if (strings.eqlComptime(filter[0], "j")) {
                                        completions = try RunCommand.completions(ctx, null, reject_list[0..], .bun_js);
                                    } else {
                                        if (strings.eqlComptime(filter[0], "z")) {
                                            completions = try RunCommand.completions(ctx, null, reject_list[0..], .script_and_descriptions);
                                        } else {
                                            if (strings.eqlComptime(filter[0], "a")) {
                                                const FirstLetter = AddCompletions.FirstLetter;
                                                _ = outer: {
                                                if (((filter.len > 1) and (filter[1].len > 0))) {
                                                    const first_letter: FirstLetter = (switch (filter[1][0]) {
'a' => FirstLetter.a,
'b' => FirstLetter.b,
'c' => FirstLetter.c,
'd' => FirstLetter.d,
'e' => FirstLetter.e,
'f' => FirstLetter.f,
'g' => FirstLetter.g,
'h' => FirstLetter.h,
'i' => FirstLetter.i,
'j' => FirstLetter.j,
'k' => FirstLetter.k,
'l' => FirstLetter.l,
'm' => FirstLetter.m,
'n' => FirstLetter.n,
'o' => FirstLetter.o,
'p' => FirstLetter.p,
'q' => FirstLetter.q,
'r' => FirstLetter.r,
's' => FirstLetter.s,
't' => FirstLetter.t,
'u' => FirstLetter.u,
'v' => FirstLetter.v,
'w' => FirstLetter.w,
'x' => FirstLetter.x,
'y' => FirstLetter.y,
'z' => FirstLetter.z,
else => break :outer,
});
                                                    _ = bun.handleOom(AddCompletions.init(bun.default_allocator));
                                                    const results = AddCompletions.getPackages(first_letter);
                                                    var prefilled_i: usize = 0;
                                                    _ = &prefilled_i;
                                                    for (cp_iter_slice(results)) |cur| {
                                                        _ = &cur;
                                                        if (((cur.len == 0) or (!strings.hasPrefix(cur, filter[1])))) {
                                                            continue;
                                                        }
                                                        prefilled_completions[cp_cast_int(usize, prefilled_i)] = cur;
                                                        prefilled_i = (prefilled_i + 1);
                                                        if ((prefilled_i >= prefilled_completions.len)) {
                                                            break;
                                                        }
                                                    }
                                                    completions.commands = prefilled_completions[0..prefilled_i];
                                                }
};
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            _ = completions.print();
    }

pub fn @"bun create"(allocator: std.mem.Allocator, log: *logger.Log) !void {
            const HardcodedNonBunXList = bun.ComptimeStringMap(void, .{ .{ "elysia" }, .{ "elysia-buchta" }, .{ "stric" } });
            const ctx = try Command.init(allocator, log, .CreateCommand);
            var args = try std.process.argsAlloc(allocator);
            _ = &args;
            if ((args.len <= 2)) {
                _ = Command.Tag.printHelp(.CreateCommand, false);
                _ = Global.exit(1);
                return;
            }
            var template_name_start: usize = 0;
            _ = &template_name_start;
            var positionals: [2][]const u8 = .{ "", "" };
            _ = &positionals;
            var positional_i: usize = 0;
            _ = &positional_i;
            var dash_dash_bun = false;
            _ = &dash_dash_bun;
            var print_help = false;
            _ = &print_help;
            if ((args.len > 2)) {
                const remainder = args[1..];
                var remainder_i: usize = 0;
                _ = &remainder_i;
                while (((remainder_i < remainder.len) and (positional_i < positionals.len))) : (remainder_i = (remainder_i + 1)) {
                    const slice = std.mem.trim(u8, bun.asByteSlice(remainder[@as(usize, @intCast(remainder_i))]), " \t\n");
                    if ((slice.len > 0)) {
                        if ((!strings.hasPrefixComptime(slice, "--"))) {
                            if ((positional_i == 1)) {
                                template_name_start = (remainder_i + 2);
                            }
                            positionals[cp_cast_int(usize, positional_i)] = slice;
                            positional_i = (positional_i + 1);
                        }
                        if ((slice[0] == 45)) {
                            if (strings.eqlComptime(slice, "--bun")) {
                                dash_dash_bun = true;
                            } else {
                                if ((strings.eqlComptime(slice, "--help") or strings.eqlComptime(slice, "-h"))) {
                                    print_help = true;
                                }
                            }
                        }
                    }
                }
            }
            if (((print_help or (positional_i == 0)) or (positionals[1].len == 0))) {
                _ = Command.Tag.printHelp(.CreateCommand, true);
                _ = Global.exit(0);
                return;
            }
            const template_name = positionals[1];
            if (strings.eqlComptime(template_name, "react")) {
                _ = Output.prettyErrorln("The \"react\" template has been deprecated.\nIt is recommended to use \"react-app\" or \"vite\" instead.\n\nTo create a project using Create React App, run\n\n  <d>bun create react-app<r>\n\nTo create a React project using Vite, run\n\n  <d>bun create vite<r>\n\nThen select \"React\" from the list of frameworks.\n", .{});
                _ = Global.exit(1);
                return;
            }
            if (strings.eqlComptime(template_name, "next")) {
                _ = Output.prettyErrorln("<yellow>warn: No template <b>create-next<r> found.\nTo create a project with the official Next.js scaffolding tool, run\n  <b>bun create next-app <cyan>[destination]<r>", .{});
                _ = Global.exit(1);
                return;
            }
            const create_command_info = try CreateCommand.extractInfo(ctx);
            const template = create_command_info.template;
            const example_tag = create_command_info.example_tag;
            const use_bunx = (((!HardcodedNonBunXList.has(template_name)) and ((!strings.containsComptime(template_name, "/")) or strings.startsWithChar(template_name, 64))) and (example_tag != CreateCommandExample.Tag.local_folder));
            if (use_bunx) {
                var bunx_args = try allocator.alloc([:0]const u8, (((2 + args.len) - template_name_start) + @intFromBool(dash_dash_bun)));
                _ = &bunx_args;
                bunx_args[cp_cast_int(usize, 0)] = "bunx";
                if (dash_dash_bun) {
                    bunx_args[cp_cast_int(usize, 1)] = "--bun";
                }
                bunx_args[cp_cast_int(usize, (1 + (if (comptime @typeInfo(@TypeOf(@intFromBool(dash_dash_bun))) == .@"enum") cp_cast_int(usize, @intFromEnum(@intFromBool(dash_dash_bun))) else cp_cast_int(usize, @intFromBool(dash_dash_bun)))))] = try BunxCommand.addCreatePrefix(allocator, template_name);
                var dst = bunx_args[(2 + (if (comptime @typeInfo(@TypeOf(@intFromBool(dash_dash_bun))) == .@"enum") cp_cast_int(usize, @intFromEnum(@intFromBool(dash_dash_bun))) else cp_cast_int(usize, @intFromBool(dash_dash_bun))))..];
                _ = &dst;
                const srcs = args[template_name_start..];
                var di: usize = 0;
                _ = &di;
                while ((di < dst.len)) : (di = (di + 1)) {
                    dst[cp_cast_int(usize, di)] = srcs[@as(usize, @intCast(di))];
                }
                const bunx_exec = BunxCommand.exec;
                _ = try bunx_exec(ctx, bunx_args);
                return;
            }
            const create_exec = CreateCommand.exec;
            _ = try create_exec(ctx, example_tag, template);
    }

pub fn @"bun info"(allocator: std.mem.Allocator, log: *logger.Log) !void {
            const cli = try PackageManager.CommandLineArguments.parse(allocator, .info);
            const ctx = try Command.init(allocator, log, .InfoCommand);
            const pm_res = try PackageManager.init(ctx, cli, PackageManager.Subcommand.info);
            const pm = pm_res[0];
            var package_name: []const u8 = "";
            _ = &package_name;
            var property_path: ?[]const u8 = null;
            _ = &property_path;
            var arg_idx: usize = 2;
            _ = &arg_idx;
            var found_package = false;
